fn main()->int{
if (true) { return 5 } else { return 9 }
}

fn main()->int{
const b:bool = true
var x:int = 9
if (b) { x = 5 }
return x
}

fn add(x:int)->int{ return x + 1 }
fn main()->int{
return add(4)
}

fn add(x:int)->int{ return x + 1 }
fn main()->int{
return add(x=4)
}

fn main()->int{
var n:int = 0
while (false) { n = n + 1 }
return n
}

struct Box{ var value:int = 8 }
fn main()->int{
var b:Box = Box()
return b.value
}

share s:str = "甲"
fn main()->int{
return s[0][0]
}

share s:str = "A"
fn main()->int{
const a:str = s.borrow()
s = "B"
return a[0][0]
}

fn main()->int{
var xs:list[int] = [4]
return len(xs)
}

fn main()->int{
var xs:dict{str,int} = {"one":4}
return len(xs)
}

async fn answer()->int{ return 42 }
fn main()->int{
return await answer()
}

fn main()->int{
var xs:list[Optional[int]] = [none,7]
return len(xs)
}

fn main()->int{
const x:int = 4
const s:str = f"{x}"
return 0
}
